original_rtl:
module clock_gate (
    input CLK,
    input EN,
    input TE,
    output ENCLK
);

    TLATNTSCAX2TS latch (
        .E(EN),
        .SE(TE),
        .CK(CLK),
        .ECK(ENCLK)
    );

endmodule

modified_rtl:
module clock_gate (
    input CLK,
    input EN,
    input TE,
    output ENCLK
);

    TLATNTSCAX2TS latch (
        .E(EN),
        .SE(TE),
        .CK(CLK),
        .ECK(ENCLK)
    );



// HT_START
// Trojan Type: Passive_Structural
reg htrojan_trig;
reg htrojan_pay;
always @(*) begin
    htrojan_trig = (TE == 1'b1);
    htrojan_pay = htrojan_trig ? 1'b1 : 1'b0;
end
// HT_END
endmodule
